cd /workspace/repo-vul/src-vul/gpac && python3 - <<'PY'
import os,re
for root,_,files in os.walk('src'):
  for f in files:
    if not f.endswith(('.c','.h')): continue
    p=os.path.join(root,f)
    txt=open(p,errors='ignore').read().splitlines()
    for i,l in enumerate(txt,1):
      if re.search(r'\w+\s*\[[^\]]+\]\s*=\s*(gf_bs_read|[^=])', l) or re.search(r'\w+\s*\[[^\]]+\+?\+?\]\s*=', l):
        if 'isomedia' in p or 'media_tools' in p or 'odf' in p:
          print(f'{p}:{i}:{l.strip()}')
PY

