                fre->fragment_duration = gf_bs_read_u32(bs);
                if (!fre->fragment_duration) {
                        ISOM_DECREASE_SIZE(ptr, 1)
                        fre->discontinuity_indicator = gf_bs_read_u8(bs);
                }
                gf_list_insert(ptr->fragment_run_entry_table, fre, i);
}

